:root {

  --text-primary: #0f172a;
  --text-title-value: #0b1220;


  --text-secondary: #8b97a8;
  --text-highlight-label: #7d8a9c;


  --text-body: #1f2937;


  --bg-default: #ffffff;
  --bg-default-hover: #fafbfd;
