  border-radius: 6px;

  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.5;

  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.025);

  transition:
    background-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}

